values (
  'es-trivia-friends',
  'Trivia fan de Friends',
  'Central Perk, Smelly Cat y diez temporadas en Nueva York: la sitcom que marcó los años 90. ¿Cuánto recuerdas de verdad?',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"¿En qué año se estrenó Friends?","options":[{"id":"a","text":"1994","is_correct":true},{"id":"b","text":"1990","is_correct":false},{"id":"c","text":"1996","is_correct":false},{"id":"d","text":"1998","is_correct":false}],"explanation":"Se estrenó el 22 de septiembre de 1994 en NBC y terminó en 2004."},{"id":"q2","question":"¿Cómo se llama la cafetería donde el grupo pasa las tardes?","options":[{"id":"a","text":"Café Nervosa","is_correct":false},{"id":"b","text":"Central Perk","is_correct":true},{"id":"c","text":"The Coffee Spot","is_correct":false},{"id":"d","text":"Java the Hut","is_correct":false}],"explanation":"Central Perk y su sofá naranja son prácticamente la segunda casa del grupo."},{"id":"q3","question":"¿En qué ciudad viven los seis amigos?","options":[{"id":"a","text":"Boston","is_correct":false},{"id":"b","text":"Los Ángeles","is_correct":false},{"id":"c","text":"Chicago","is_correct":false},{"id":"d","text":"Nueva York","is_correct":true}],"explanation":"Viven en Manhattan: el apartamento morado de Mónica está en el Village."},{"id":"q4","question":"¿Cuál es la profesión de Ross?","options":[{"id":"a","text":"Arqueólogo","is_correct":false},{"id":"b","text":"Chef","is_correct":false},{"id":"c","text":"Paleontólogo","is_correct":true},{"id":"d","text":"Actor","is_correct":false}],"explanation":"Ross es paleontólogo; su pasión por los dinosaurios es un chiste recurrente."},{"id":"q5","question":"¿Cómo se llama el mono que Ross tiene como mascota?","options":[{"id":"a","text":"Marcel","is_correct":true},{"id":"b","text":"Maurice","is_correct":false},{"id":"c","text":"Marcelo","is_correct":false},{"id":"d","text":"Mateo","is_correct":false}],"explanation":"Marcel, el mono capuchino, vive con Ross durante la primera temporada."},{"id":"q6","question":"¿A quién deja Rachel plantado en el altar en el primer episodio?","options":[{"id":"a","text":"A Ross","is_correct":false},{"id":"b","text":"A Barry","is_correct":true},{"id":"c","text":"A Paolo","is_correct":false},{"id":"d","text":"A Joshua","is_correct":false}],"explanation":"Rachel entra a Central Perk con el vestido de novia tras abandonar a Barry en la boda."},{"id":"q7","question":"¿Cuál es la frase con la que Joey intenta ligar?","options":[{"id":"a","text":"''We were on a break!''","is_correct":false},{"id":"b","text":"''Pivot!''","is_correct":false},{"id":"c","text":"''Oh. My. God.''","is_correct":false},{"id":"d","text":"''How you doin''?''","is_correct":true}],"explanation":"''How you doin''?'' es el clásico de Joey; ''We were on a break!'' y ''Pivot!'' son de Ross, y ''Oh. My. God.'' es de Janice."},{"id":"q8","question":"¿Cómo se llama la hermana gemela de Phoebe?","options":[{"id":"a","text":"Jill","is_correct":false},{"id":"b","text":"Amy","is_correct":false},{"id":"c","text":"Ursula","is_correct":true},{"id":"d","text":"Mindy","is_correct":false}],"explanation":"Ursula, interpretada también por Lisa Kudrow, viene de Mad About You; Jill y Amy son las hermanas de Rachel."}]'::jsonb,
