values (
  'en-the-office-trivia',
  'The Office Fan Trivia Challenge',
  'Dunder Mifflin''s Scranton branch gave us nine seasons of cringe and heart. Test how well you know Michael Scott and company.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"In which Pennsylvania city is the Dunder Mifflin branch located?","options":[{"id":"a","text":"Utica","is_correct":false},{"id":"b","text":"Scranton","is_correct":true},{"id":"c","text":"Stamford","is_correct":false},{"id":"d","text":"Buffalo","is_correct":false}],"explanation":"Scranton, ''the Electric City'' — Utica, Stamford and Buffalo are other branches seen in the series."},{"id":"q2","question":"Who plays regional manager Michael Scott?","options":[{"id":"a","text":"John Krasinski","is_correct":false},{"id":"b","text":"Rainn Wilson","is_correct":false},{"id":"c","text":"Steve Carell","is_correct":true},{"id":"d","text":"Ed Helms","is_correct":false}],"explanation":"Steve Carell played Michael from the pilot until his farewell in season 7."},{"id":"q3","question":"In which year did the U.S. version of The Office premiere?","options":[{"id":"a","text":"2001","is_correct":false},{"id":"b","text":"2007","is_correct":false},{"id":"c","text":"2009","is_correct":false},{"id":"d","text":"2005","is_correct":true}],"explanation":"NBC premiered it in March 2005; 2001 is the year of the U.K. original."},{"id":"q4","question":"In the first episode, what does Jim put Dwight''s stapler inside?","options":[{"id":"a","text":"A Jell-O mold","is_correct":true},{"id":"b","text":"The office fridge","is_correct":false},{"id":"c","text":"A drawer full of coins","is_correct":false},{"id":"d","text":"Pam''s filing cabinet","is_correct":false}],"explanation":"The stapler-in-Jell-O prank in the pilot set the tone for Jim and Dwight''s whole rivalry."},{"id":"q5","question":"What crop is Schrute Farms famous for?","options":[{"id":"a","text":"Corn","is_correct":false},{"id":"b","text":"Beets","is_correct":true},{"id":"c","text":"Pumpkins","is_correct":false},{"id":"d","text":"Soybeans","is_correct":false}],"explanation":"Dwight''s family farm grows beets — hence ''Bears. Beets. Battlestar Galactica.''"},{"id":"q6","question":"What does Michael call the award show he hosts for his employees?","options":[{"id":"a","text":"The Mifflins","is_correct":false},{"id":"b","text":"The Scranton Emmys","is_correct":false},{"id":"c","text":"The Dundies","is_correct":true},{"id":"d","text":"The Paperies","is_correct":false}],"explanation":"The Dundies take place at the local Chili''s, where Pam famously gets banned."},{"id":"q7","question":"What is the title of the amateur spy film Michael spent years making?","options":[{"id":"a","text":"Goldenface","is_correct":false},{"id":"b","text":"Threat Level Midnight","is_correct":true},{"id":"c","text":"The Scranton Strangler","is_correct":false},{"id":"d","text":"Agent Paper","is_correct":false}],"explanation":"Threat Level Midnight stars Michael as agent Michael Scarn; Goldenface is the villain, not the title."},{"id":"q8","question":"What is Pam''s job at Dunder Mifflin when the series begins?","options":[{"id":"a","text":"Saleswoman","is_correct":false},{"id":"b","text":"Accountant","is_correct":false},{"id":"c","text":"HR representative","is_correct":false},{"id":"d","text":"Receptionist","is_correct":true}],"explanation":"Pam Beesly answers the phones at reception; she later moves into sales and office administration."}]'::jsonb,
  null,
  array['the office', 'tv-shows', 'comedy', 'trivia']::text[],
  3,
  'published',
