  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'movies-tv'),
  '[{"id":"q1","question":"¿Cómo se llama la empresa de papel donde trabajan Michael, Jim, Pam y Dwight?","options":[{"id":"a","text":"Sabre","is_correct":false},{"id":"b","text":"Prince Family Paper","is_correct":false},{"id":"c","text":"Dunder Mifflin","is_correct":true},{"id":"d","text":"Michael Scott Paper Company","is_correct":false}],"explanation":"Dunder Mifflin es la compañía; Sabre la compra más adelante y las otras dos son una competidora y la empresa que funda Michael."},{"id":"q2","question":"¿En qué ciudad de Pensilvania está la sucursal?","options":[{"id":"a","text":"Scranton","is_correct":true},{"id":"b","text":"Utica","is_correct":false},{"id":"c","text":"Nashua","is_correct":false},{"id":"d","text":"Stamford","is_correct":false}],"explanation":"Scranton, la ''Electric City''; Utica, Nashua y Stamford son otras sucursales que aparecen en la serie."},{"id":"q3","question":"¿Quién interpreta a Michael Scott?","options":[{"id":"a","text":"John Krasinski","is_correct":false},{"id":"b","text":"Steve Carell","is_correct":true},{"id":"c","text":"Ed Helms","is_correct":false},{"id":"d","text":"B.J. Novak","is_correct":false}],"explanation":"Steve Carell interpretó a Michael hasta su despedida en la séptima temporada."},{"id":"q4","question":"¿Qué cultiva Dwight en la granja familiar, Schrute Farms?","options":[{"id":"a","text":"Maíz","is_correct":false},{"id":"b","text":"Zapallos","is_correct":false},{"id":"c","text":"Remolacha","is_correct":true},{"id":"d","text":"Papas","is_correct":false}],"explanation":"Remolacha (beets): de ahí sale ''Bears. Beets. Battlestar Galactica.''"},{"id":"q5","question":"¿Cuál es la frase que Michael repite siempre que puede?","options":[{"id":"a","text":"''That''s what she said''","is_correct":true},{"id":"b","text":"''Bears. Beets. Battlestar Galactica.''","is_correct":false},{"id":"c","text":"''Did I stutter?''","is_correct":false},{"id":"d","text":"''Assistant to the regional manager''","is_correct":false}],"explanation":"''That''s what she said'' es el clásico de Michael; la segunda es Jim imitando a Dwight, la tercera es de Stanley y la última es el cargo que Dwight reclama."},{"id":"q6","question":"¿Cómo se llama la película casera de espionaje que Michael rodó durante años?","options":[{"id":"a","text":"Goldenface","is_correct":false},{"id":"b","text":"Scranton Vice","is_correct":false},{"id":"c","text":"Threat Level Midnight","is_correct":true},{"id":"d","text":"La amenaza de Scranton","is_correct":false}],"explanation":"Threat Level Midnight, protagonizada por Michael como el agente Michael Scarn; Goldenface es el villano."},{"id":"q7","question":"¿Qué puesto tiene Pam cuando empieza la serie?","options":[{"id":"a","text":"Contable","is_correct":false},{"id":"b","text":"Recepcionista","is_correct":true},{"id":"c","text":"Vendedora","is_correct":false},{"id":"d","text":"Directora de oficina","is_correct":false}],"explanation":"Pam Beesly empieza en recepción; después pasa a ventas y a administración de la oficina."},{"id":"q8","question":"¿Cuántas temporadas tiene The Office (EE. UU.)?","options":[{"id":"a","text":"7","is_correct":false},{"id":"b","text":"8","is_correct":false},{"id":"c","text":"10","is_correct":false},{"id":"d","text":"9","is_correct":true}],"explanation":"Nueve temporadas, de 2005 a 2013."}]'::jsonb,
