values (
  'en-dragon-ball-trivia',
  'Dragon Ball Fan Trivia Challenge',
  'From Goku''s first Kamehameha to the battles on Namek: the Akira Toriyama classic that defined anime for generations.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'anime-manga'),
  '[{"id":"q1","question":"Who created Dragon Ball?","options":[{"id":"a","text":"Eiichiro Oda","is_correct":false},{"id":"b","text":"Masashi Kishimoto","is_correct":false},{"id":"c","text":"Akira Toriyama","is_correct":true},{"id":"d","text":"Tite Kubo","is_correct":false}],"explanation":"Akira Toriyama created the manga in 1984; Oda, Kishimoto and Kubo created One Piece, Naruto and Bleach."},{"id":"q2","question":"How many Dragon Balls must be gathered to summon the wish-granting dragon?","options":[{"id":"a","text":"Five","is_correct":false},{"id":"b","text":"Seven","is_correct":true},{"id":"c","text":"Nine","is_correct":false},{"id":"d","text":"Twelve","is_correct":false}],"explanation":"Seven balls summon Shenron, who grants a wish before the balls scatter again."},{"id":"q3","question":"What is Goku''s Saiyan birth name?","options":[{"id":"a","text":"Raditz","is_correct":false},{"id":"b","text":"Kakarot","is_correct":true},{"id":"c","text":"Bardock","is_correct":false},{"id":"d","text":"Vegeta","is_correct":false}],"explanation":"Kakarot — Raditz is his brother, Bardock his father and Vegeta his prince."},{"id":"q4","question":"What is Goku''s signature energy wave?","options":[{"id":"a","text":"Galick Gun","is_correct":false},{"id":"b","text":"Special Beam Cannon","is_correct":false},{"id":"c","text":"Final Flash","is_correct":false},{"id":"d","text":"Kamehameha","is_correct":true}],"explanation":"The Kamehameha; Galick Gun and Final Flash are Vegeta''s and the Special Beam Cannon is Piccolo''s."},{"id":"q5","question":"Who is the prince of the Saiyans?","options":[{"id":"a","text":"Vegeta","is_correct":true},{"id":"b","text":"Nappa","is_correct":false},{"id":"c","text":"Raditz","is_correct":false},{"id":"d","text":"Broly","is_correct":false}],"explanation":"Vegeta, prince of all Saiyans — Nappa and Raditz are fellow survivors, not royalty."},{"id":"q6","question":"On which planet does Goku first transform into a Super Saiyan?","options":[{"id":"a","text":"Earth","is_correct":false},{"id":"b","text":"Namek","is_correct":true},{"id":"c","text":"Yardrat","is_correct":false},{"id":"d","text":"Planet Vegeta","is_correct":false}],"explanation":"On Namek, fighting Frieza — Planet Vegeta was already destroyed and he reached Yardrat afterwards."},{"id":"q7","question":"Who is the Namekian that starts as Goku''s enemy and later trains Gohan?","options":[{"id":"a","text":"Nail","is_correct":false},{"id":"b","text":"Kami","is_correct":false},{"id":"c","text":"Piccolo","is_correct":true},{"id":"d","text":"Dende","is_correct":false}],"explanation":"Piccolo — Nail and Dende are other Namekians and Kami is Earth''s guardian."},{"id":"q8","question":"In which magazine did the Dragon Ball manga debut in 1984?","options":[{"id":"a","text":"Weekly Shōnen Jump","is_correct":true},{"id":"b","text":"Weekly Shōnen Magazine","is_correct":false},{"id":"c","text":"CoroCoro Comic","is_correct":false},{"id":"d","text":"Ultra Jump","is_correct":false}],"explanation":"Shueisha''s Weekly Shōnen Jump — the same magazine that later ran One Piece and Naruto."}]'::jsonb,
  null,
  array['dragon ball', 'anime', 'goku', 'trivia']::text[],
