  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'anime-manga'),
  '[{"id":"q1","question":"¿Quién creó Dragon Ball?","options":[{"id":"a","text":"Akira Toriyama","is_correct":true},{"id":"b","text":"Eiichiro Oda","is_correct":false},{"id":"c","text":"Hayao Miyazaki","is_correct":false},{"id":"d","text":"Masashi Kishimoto","is_correct":false}],"explanation":"Akira Toriyama publicó el manga en 1984; Oda es el autor de One Piece y Miyazaki dirige cine de animación."},{"id":"q2","question":"¿Cuántas esferas del dragón hay que reunir para invocar al dragón que concede deseos?","options":[{"id":"a","text":"3","is_correct":false},{"id":"b","text":"5","is_correct":false},{"id":"c","text":"7","is_correct":true},{"id":"d","text":"9","is_correct":false}],"explanation":"Siete: al juntarlas aparece Shenron, concede el deseo y las esferas se dispersan de nuevo."},{"id":"q3","question":"¿De quién aprende Goku el Kamehameha?","options":[{"id":"a","text":"De Kaio-sama","is_correct":false},{"id":"b","text":"Del Maestro Roshi","is_correct":true},{"id":"c","text":"De Kami","is_correct":false},{"id":"d","text":"De Karin","is_correct":false}],"explanation":"Lo copia del Maestro Roshi, su inventor, tras verlo usarlo una sola vez."},{"id":"q4","question":"¿Cómo se llama el hijo mayor de Goku?","options":[{"id":"a","text":"Goten","is_correct":false},{"id":"b","text":"Gohan","is_correct":true},{"id":"c","text":"Trunks","is_correct":false},{"id":"d","text":"Krilin","is_correct":false}],"explanation":"Gohan, llamado así por el abuelo que crió a Goku; Goten es el hermano menor."},{"id":"q5","question":"¿Qué villano destruye el planeta Vegeta?","options":[{"id":"a","text":"Cell","is_correct":false},{"id":"b","text":"Majin Buu","is_correct":false},{"id":"c","text":"Piccolo","is_correct":false},{"id":"d","text":"Freezer","is_correct":true}],"explanation":"Freezer destruyó el planeta natal de los saiyajin por miedo a la leyenda del Super Saiyajin."},{"id":"q6","question":"¿Qué aparato inventa Bulma para localizar las esferas del dragón?","options":[{"id":"a","text":"El radar del dragón","is_correct":true},{"id":"b","text":"La máquina del tiempo","is_correct":false},{"id":"c","text":"Las cápsulas Hoi-Poi","is_correct":false},{"id":"d","text":"El rastreador de ki","is_correct":false}],"explanation":"Bulma construye el radar del dragón con el que ella y Goku empiezan la búsqueda."},{"id":"q7","question":"¿Cómo se llama el mejor amigo calvo de Goku?","options":[{"id":"a","text":"Yamcha","is_correct":false},{"id":"b","text":"Ten Shin Han","is_correct":false},{"id":"c","text":"Krilin","is_correct":true},{"id":"d","text":"Oolong","is_correct":false}],"explanation":"Krilin entrenó con Goku bajo el Maestro Roshi y se convirtió en su mejor amigo."},{"id":"q8","question":"¿En qué revista se publicó por primera vez el manga de Dragon Ball?","options":[{"id":"a","text":"Nakayoshi","is_correct":false},{"id":"b","text":"Weekly Shōnen Jump","is_correct":true},{"id":"c","text":"CoroCoro Comic","is_correct":false},{"id":"d","text":"Weekly Shōnen Sunday","is_correct":false}],"explanation":"En la Weekly Shōnen Jump de Shueisha, en 1984."}]'::jsonb,
