is_correct":false},{"id":"b","text":"Adopt Me!","is_correct":true},{"id":"c","text":"Tower of Hell","is_correct":false},{"id":"d","text":"Natural Disaster Survival","is_correct":false}],"explanation":"Adopt Me! is one of the most visited experiences on the whole platform."},{"id":"q7","question":"What do players do in Jailbreak?","options":[{"id":"a","text":"Deliver pizzas","is_correct":false},{"id":"b","text":"Survive zombie waves","is_correct":false},{"id":"c","text":"Escape prison and rob banks — or stop them as police","is_correct":true},{"id":"d","text":"Build and defend a castle","is_correct":false}],"explanation":"Jailbreak pits criminals against police; delivering pizzas is Work at a Pizza Place."},{"id":"q8","question":"What classic Roblox sound became a meme before being removed in 2022?","options":[{"id":"a","text":"''Yeet''","is_correct":false},{"id":"b","text":"''Boop''","is_correct":false},{"id":"c","text":"''Oof''","is_correct":true},{"id":"d","text":"''Meep''","is_correct":false}],"explanation":"The ''oof'' death sound was replaced in 2022 after a licensing dispute — and lives on as a meme."}]'::jsonb,
