  '[{"id":"q1","question":"¿Qué estudio desarrolla Fortnite?","options":[{"id":"a","text":"Epic Games","is_correct":true},{"id":"b","text":"Riot Games","is_correct":false},{"id":"c","text":"Blizzard","is_correct":false},{"id":"d","text":"Valve","is_correct":false}],"explanation":"Epic Games, el mismo estudio detrás del motor Unreal."},{"id":"q2","question":"¿En qué año se lanzó el modo Battle Royale?","options":[{"id":"a","text":"2016","is_correct":false},{"id":"b","text":"2017","is_correct":true},{"id":"c","text":"2018","is_correct":false},{"id":"d","text":"2019","is_correct":false}],"explanation":"En septiembre de 2017, pocos meses después del modo original Salvar el Mundo."},{"id":"q3","question":"¿Cuántos jugadores caen en una partida estándar de Battle Royale?","options":[{"id":"a","text":"60","is_correct":false},{"id":"b","text":"80","is_correct":false},{"id":"c","text":"100","is_correct":true},{"id":"d","text":"150","is_correct":false}],"explanation":"Cien jugadores saltan del autobús y gana el último que queda en pie."},{"id":"q4","question":"¿Cómo se llama el vehículo volador desde el que saltan los jugadores al inicio?","options":[{"id":"a","text":"El helicóptero de botín","is_correct":false},{"id":"b","text":"El dirigible del tesoro","is_correct":false},{"id":"c","text":"El autobús de batalla","is_correct":true},{"id":"d","text":"El tren de suministros","is_correct":false}],"explanation":"El Battle Bus: hasta puedes agradecer al conductor antes de saltar."},{"id":"q5","question":"¿Qué mensaje aparece en pantalla al ganar una partida?","options":[{"id":"a","text":"''¡Winner winner chicken dinner!''","is_correct":false},{"id":"b","text":"''¡Eres el campeón!''","is_correct":false},{"id":"c","text":"''Partida terminada''","is_correct":false},{"id":"d","text":"''¡Victoria Magistral!''","is_correct":true}],"explanation":"La ''Victoria Magistral'' es el Victory Royale; ''winner winner chicken dinner'' es el de PUBG."},{"id":"q6","question":"¿Con qué moneda se compran skins y pases dentro del juego?","options":[{"id":"a","text":"Con pavos (V-Bucks)","is_correct":true},{"id":"b","text":"Con gemas","is_correct":false},{"id":"c","text":"Con Robux","is_correct":false},{"id":"d","text":"Con monedas de oro","is_correct":false}],"explanation":"Los pavos (V-Bucks) compran skins, gestos y el pase de batalla; los Robux son de Roblox."},{"id":"q7","question":"¿Cómo se llama el modo cooperativo original de Fortnite, de hordas y defensa?","options":[{"id":"a","text":"Cero construcción","is_correct":false},{"id":"b","text":"Batalla campal","is_correct":false},{"id":"c","text":"Salvar el Mundo","is_correct":true},{"id":"d","text":"Modo creativo","is_correct":false}],"explanation":"Salvar el Mundo es el modo PvE original; el Battle Royale llegó después y se hizo más famoso."},{"id":"q8","question":"¿Qué herramienta usan los jugadores para recolectar materiales de construcción?","options":[{"id":"a","text":"La pala","is_correct":false},{"id":"b","text":"El hacha","is_correct":false},{"id":"c","text":"El martillo","is_correct":false},{"id":"d","text":"El pico","is_correct":true}],"explanation":"El pico (pickaxe): también es el primer objeto cosmético que se personaliza."}]'::jsonb,
